from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[2];O=R/'renders/references_54d3731';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data=[]
for s in m['scenes']:
 data.append({**s,'images':{mode:{name:uri(O/s['id']/mode/(name+'.png')) for name in names} for mode,names in s['layers'].items()}})
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Références 54d3731 · entrées multicouches</title><style>*{box-sizing:border-box}body{background:#122326;color:#edf3e9;font:16px system-ui;margin:0}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:27px;margin:8px 0}p{color:#b4cebf;line-height:1.6}.tag{color:#a9dba1;font-size:12px;letter-spacing:2px}.bar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:10px;background:#2a443b;color:white;border:1px solid #6b8d78;border-radius:6px}.view{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:24px}canvas{width:100%;max-height:740px;object-fit:contain;image-rendering:pixelated;background:repeating-conic-gradient(#253b35 0% 25%,#21332e 0% 50%) 50%/20px 20px}aside{padding:15px;background:#1d342d;border-radius:8px}label{display:block;font-size:14px;margin:15px 0}a{color:#a9e8b5}small{color:#bbd1bc}footer{border-top:1px solid #466050}@media(max-width:800px){.view{grid-template-columns:1fr}}</style><header><div class="tag">RÉFÉRENCES DU COMMIT 54D3731</div><h1>Dix scènes · entrées de zone & calques séparés</h1><p>La première grotte est dans l’axe du chemin, avec feuillage vert et terre brune. Energetic Forest, Mushroom Forest et Waterfall Lake deviennent des entrées naturelles en conservant leur composition reconnaissable. Aucune animation ajoutée.</p></header><main><div class="bar"><select id="scene"></select><select id="mode"><option value="jour">Jour / ambiance de base</option><option value="nuit">Nuit · filtre Abyss</option></select><button id="all">Afficher tous les calques</button><button id="export">Exporter la composition PNG</button></div><div class="view"><section><canvas id="canvas" width="400" height="320"></canvas><p id="status"></p><p id="notes"></p></section><aside><b>Calques visibles</b><div id="layers"></div><small>↓ télécharge le PNG transparent. Les calques gardent leur position sur la toile de la scène.</small></aside></div></main><footer><p>Les calques de terrain sont des partitions de profondeur du dessin généré : leur recomposition est exacte, mais les surfaces cachées ne sont pas reconstruites. Aucun ajout de lune à une pièce intérieure ou à une forêt sans ciel visible.</p><small>Les dessins sont guidés par les références, pas certifiés identiques à des tuiles natives. Les passages sont visuels : aucune collision ou transition PMDO n’est intégrée. Sources originales et premiers essais conservés.</small></footer><script>const DATA=__DATA__;function image(s){const i=new Image();i.src=s;return i}let index=0,mode='jour',images={},visible={};const c=document.getElementById('canvas'),ctx=c.getContext('2d');function save(src,name){const a=document.createElement('a');a.href=src;a.download=name;a.click()}DATA.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(i+1).padStart(2,'0')+' · '+s.title;document.getElementById('scene').append(o)});function setup(){const s=DATA[index];[c.width,c.height]=s.size;visible={};images={};const root=document.getElementById('layers');root.innerHTML='';for(const [name,src]of Object.entries(s.images[mode])){images[name]=image(src);visible[name]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[name]=ch.checked;a.href=src;a.download=s.id+'_'+mode+'_'+name+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(' '+name.replaceAll('_',' ')),a);root.append(l)}document.getElementById('status').textContent=s.title+' · '+s.size.join(' × ')+' · '+Object.keys(images).length+' calques · statique';document.getElementById('notes').textContent=s.notes.join(' ')}document.getElementById('scene').onchange=e=>{index=Number(e.target.value);setup()};document.getElementById('mode').onchange=e=>{mode=e.target.value;setup()};document.getElementById('all').onclick=setup;document.getElementById('export').onclick=()=>save(c.toDataURL(),DATA[index].id+'_'+mode+'.png');function draw(){ctx.clearRect(0,0,c.width,c.height);for(const [name,i]of Object.entries(images))if(visible[name]&&i.complete&&i.naturalWidth)ctx.drawImage(i,0,0);requestAnimationFrame(draw)}setup();requestAnimationFrame(draw);</script></html>'''
(R/'apercu_references_54d3731.html').write_text(h.replace('__DATA__',json.dumps(data)),encoding='utf8');print('Static gallery ready for 20 scenes')
